        List<LiquidResources.Lease> FillLiquidBudget(int spare=0){
            var held=new List<LiquidResources.Lease>();int count=LiquidResources.MaximumInstances-(int)LiquidResources.ObserveBudget()["instances"]-spare;
            try{for(int i=0;i<count;i++)held.Add(LiquidResources.Begin(new RoomResourceOwner(editor.WorldIdentity,Guid.NewGuid().ToString("N"),"liquid")));return held;}catch{ReleaseLiquidBudget(held);throw;}
        }
        static void ReleaseLiquidBudget(IEnumerable<LiquidResources.Lease> leases){foreach(var lease in leases)lease.Dispose();}
        static RoomObjectData LiquidAdmissionData(){var data=NativeObjectAdmissionFixture.Data();data.containers=new[]{new RoomContainer{amountMl=100}};return data;}
        JObject[] LiquidReservations(string target){var budget=CollisionFact("runtime.liquidBudget");return Enumerable.Range(0,(int)budget["instances"]).Select(i=>CollisionFact("runtime.liquidReservation",new JObject{["index"]=i})).Where(x=>(string)x["target"]==target).ToArray();}
        [UnityTest]public IEnumerator LiquidAdmissionFullBudgetPreservesSavedCreationAndRedoCanRetry(){
            Assert.That(editor.TryFlush(out var error),Is.True,error);var data=LiquidAdmissionData();string saved=JsonUtility.ToJson(editor.Snapshot());var bytes=File.ReadAllBytes(Path.Combine(directory,RoomStorage.FileName));int revision=editor.Revision;bool undo=editor.CanUndo,redo=editor.CanRedo;var held=FillLiquidBudget();
            try{Assert.That(editor.ApplyAgentEdit(editor.Revision,new[]{data},Array.Empty<string>(),out error),Is.False);StringAssert.Contains("liquid budget",error);Assert.That(editor.Revision,Is.EqualTo(revision));Assert.That(editor.CanUndo,Is.EqualTo(undo));Assert.That(editor.CanRedo,Is.EqualTo(redo));Assert.That(JsonUtility.ToJson(editor.Snapshot()),Is.EqualTo(saved));CollectionAssert.AreEqual(bytes,File.ReadAllBytes(Path.Combine(directory,RoomStorage.FileName)));Assert.That(editor.Find(data.id),Is.Null);Assert.That(editor.PaintObject(editor.Identity(block),Color.blue,out error),Is.True,error);}finally{ReleaseLiquidBudget(held);}
            Assert.That(editor.ApplyAgentEdit(editor.Revision,new[]{data},Array.Empty<string>(),out error),Is.True,error);editor.Undo();yield return null;held=FillLiquidBudget();revision=editor.Revision;
            try{editor.Redo();Assert.That(editor.Revision,Is.EqualTo(revision));Assert.That(editor.Find(data.id),Is.Null);Assert.That(editor.CanRedo,Is.True);}finally{ReleaseLiquidBudget(held);}editor.Redo();Assert.That(editor.Find(data.id).GetComponent<ContainerFillView>().NativeReady,Is.True);Assert.That(editor.Read(data.id).containers[0].amountMl,Is.EqualTo(100));
        }
        [UnityTest]public IEnumerator LiquidAdmissionFailedInitialSaveAndLateBatchRetireOnlyPrivateResources(){
            Assert.That(editor.TryFlush(out var error),Is.True,error);string saved=JsonUtility.ToJson(editor.Snapshot()),budget=LiquidResources.ObserveBudget().ToString();int revision=editor.Revision;var bytes=File.ReadAllBytes(Path.Combine(directory,RoomStorage.FileName));string pending=Path.Combine(directory,RoomStorage.FileName+".pending");Directory.CreateDirectory(pending);
            try{Assert.That(editor.EditContainer(editor.Identity(block),editor.ObjectRevision(editor.Identity(block)),new RoomContainer{amountMl=100},out error),Is.False);}finally{Directory.Delete(pending);}Assert.That(block.GetComponent<ContainerFillView>(),Is.Null);Assert.That((int)LiquidResources.ObserveBudget()["retiring"],Is.EqualTo(1));Assert.That(editor.Revision,Is.EqualTo(revision));Assert.That(JsonUtility.ToJson(editor.Snapshot()),Is.EqualTo(saved));CollectionAssert.AreEqual(bytes,File.ReadAllBytes(Path.Combine(directory,RoomStorage.FileName)));yield return null;Assert.That(LiquidResources.ObserveBudget().ToString(),Is.EqualTo(budget));
            var first=LiquidAdmissionData();var second=LiquidAdmissionData();var held=FillLiquidBudget(1);
            try{Assert.That(editor.ApplyAgentEdit(editor.Revision,new[]{first,second},Array.Empty<string>(),out error),Is.False);StringAssert.Contains("liquid budget",error);Assert.That((int)LiquidResources.ObserveBudget()["retiring"],Is.EqualTo(1));Assert.That(editor.Revision,Is.EqualTo(revision));Assert.That(JsonUtility.ToJson(editor.Snapshot()),Is.EqualTo(saved));CollectionAssert.AreEqual(bytes,File.ReadAllBytes(Path.Combine(directory,RoomStorage.FileName)));Assert.That(editor.Find(first.id),Is.Null);Assert.That(editor.Find(second.id),Is.Null);yield return null;Assert.That((int)LiquidResources.ObserveBudget()["instances"],Is.EqualTo(31));}finally{ReleaseLiquidBudget(held);}
        }
        [UnityTest]public IEnumerator LiquidAdmissionFullBudgetReusesEmptyFillAndShapeEditsThenRemovalWaitsForDestruction(){
            var(_,from,to)=Containers();var a=editor.Find(from).GetComponent<ContainerFillView>();var b=editor.Find(to).GetComponent<ContainerFillView>();var one=a.ReusableReservation;var two=b.ReusableReservation;Assert.That(two.Surface.activeSelf,Is.False);Assert.That(two.Stream,Is.Not.Null);var held=FillLiquidBudget();
            try{Assert.That(editor.TransferContainer(from,editor.ObjectRevision(from),to,editor.ObjectRevision(to),50,out var moved,out var error),Is.True,error);Assert.That(moved,Is.EqualTo(50));Assert.That(a.ReusableReservation,Is.SameAs(one));Assert.That(b.ReusableReservation,Is.SameAs(two));Assert.That(two.Surface.activeSelf,Is.True);var changed=editor.Read(from).containers[0];changed.radius=.06f;changed.color=Color.green;Assert.That(editor.EditContainer(from,editor.ObjectRevision(from),changed,out error),Is.True,error);Assert.That(a.ReusableReservation,Is.SameAs(one));Assert.That((int)LiquidResources.ObserveBudget()["instances"],Is.EqualTo(32));
                Assert.That(editor.EditContainer(to,editor.ObjectRevision(to),null,out error),Is.True,error);Assert.That(b.ReusableReservation,Is.Null);Assert.That(two.Phase,Is.EqualTo("retiring"));Assert.That(two.Surface.activeSelf||two.Stream.activeSelf,Is.False);Assert.Throws<RoomResourceLimitException>(()=>LiquidResources.Begin(new RoomResourceOwner(editor.WorldIdentity,"next","liquid")));yield return null;Assert.That((int)LiquidResources.ObserveBudget()["instances"],Is.EqualTo(31));Assert.That(!two.Surface&&!two.Stream&&!two.Mesh&&!two.SurfaceMaterial&&!two.StreamMaterial,Is.True);
            }finally{ReleaseLiquidBudget(held);}
        }
        [UnityTest]public IEnumerator LiquidAdmissionPhysicalPourUsesPreparedEmptyDestinationAndStreamAtFullBudget(){
            var(_,from,to)=PouringCups();var source=editor.Find(from).GetComponent<ContainerFillView>().ReusableReservation;var destination=editor.Find(to).GetComponent<ContainerFillView>().ReusableReservation;var held=FillLiquidBudget();
            try{Assert.That(destination.Surface.activeSelf,Is.False);Assert.That(source.Line.enabled,Is.False);editor.Liquids.Tick(.05f);Assert.That(source.Line.enabled,Is.True);Assert.That(destination.Surface.activeSelf,Is.True);double left=(double)editor.Liquids.Observe(from)["contents"]["amountMl"],right=(double)editor.Liquids.Observe(to)["contents"]["amountMl"];Assert.That(right,Is.GreaterThan(0));Assert.That(left+right,Is.EqualTo(400).Within(1e-8));Assert.That(editor.Read(to).containers[0].amountMl,Is.Zero);physics.PausePhysics();Assert.That(editor.Read(to).containers[0].amountMl,Is.EqualTo(right));Assert.That(editor.Find(from).GetComponent<ContainerFillView>().ReusableReservation,Is.SameAs(source));Assert.That(editor.Find(to).GetComponent<ContainerFillView>().ReusableReservation,Is.SameAs(destination));Assert.That(source.Line.enabled,Is.False);Assert.That((int)LiquidResources.ObserveBudget()["instances"],Is.EqualTo(32));}finally{ReleaseLiquidBudget(held);}yield return null;
        }
        [UnityTest]public IEnumerator LiquidAdmissionTemporaryDiscardAndDormantActivationPreserveWaterAndRetry(){
            var(_,from,_)=Containers();Assert.That(editor.BeginTemporaryRoom(out var error),Is.True,error);while(editor.TemporarySavePending)yield return null;Assert.That(editor.EditContainer(from,editor.ObjectRevision(from),null,out error),Is.True,error);yield return null;string session=editor.TemporarySessionId;var held=FillLiquidBudget();
            try{Assert.That(editor.DiscardTemporaryRoom(out error),Is.False);StringAssert.Contains("liquid budget",error);Assert.That(editor.TemporarySessionId,Is.EqualTo(session));Assert.That(editor.Read(from).containers,Is.Empty);}finally{ReleaseLiquidBudget(held);}Assert.That(editor.DiscardTemporaryRoom(out error),Is.True,error);Assert.That(editor.Read(from).containers[0].amountMl,Is.EqualTo(200));
            string area=NativeAreaFor(from);Assert.That(editor.RetireNativeArea(area,out error),Is.True,error);yield return null;held=FillLiquidBudget();int revision=editor.Revision;string saved=JsonUtility.ToJson(editor.Snapshot());
            try{yield return NativeAreaCompletion(editor.ActivateNativeArea(area),false);Assert.That(editor.Find(from),Is.Null);Assert.That(editor.NativeEntityDormant(from),Is.True);Assert.That(editor.Revision,Is.EqualTo(revision));Assert.That(JsonUtility.ToJson(editor.Snapshot()),Is.EqualTo(saved));}finally{ReleaseLiquidBudget(held);}yield return NativeAreaCompletion(editor.ActivateNativeArea(area));Assert.That(editor.Find(from).GetComponent<ContainerFillView>().NativeReady,Is.True);Assert.That(editor.Read(from).containers[0].amountMl,Is.EqualTo(200));
        }
        [UnityTest]public IEnumerator LiquidAdmissionLostWaterViewHoldsNearbyPhysicsAndUnrelatedEditsCannotRepairIt(){
            var(pool,prop)=MediumFixture(.1f);var point=new Vector3(4,1.4f,0);Assert.That((bool)MediumAt(point)["found"],Is.True);var view=editor.Find(pool).GetComponent<ContainerFillView>();UnityEngine.Object.DestroyImmediate(view);yield return null;var value=MediumAt(point);Assert.That((string)value["availability"],Is.EqualTo("unavailable"));Assert.That((bool)value["found"],Is.False);var body=editor.Find(prop).GetComponent<RigidRoomItem>();body.Refresh();Assert.That(editor.Find(prop).GetComponent<Rigidbody>().isKinematic,Is.True);physics.PausePhysics();var held=FillLiquidBudget();
            try{Assert.That(editor.PaintObject(editor.Identity(block),Color.blue,out var error),Is.True,error);Assert.That(editor.Find(pool).GetComponent<ContainerFillView>(),Is.Null);Assert.That((string)MediumAt(point)["availability"],Is.EqualTo("unavailable"));int revision=editor.Revision;Assert.That(editor.PaintObject(pool,Color.green,out error),Is.False);StringAssert.Contains("liquid budget",error);Assert.That(editor.Revision,Is.EqualTo(revision));}finally{ReleaseLiquidBudget(held);}Assert.That(editor.PaintObject(pool,Color.green,out var issue),Is.True,issue);Assert.That(editor.Find(pool).GetComponent<ContainerFillView>().NativeReady,Is.True);Assert.That((bool)MediumAt(point)["found"],Is.True);Assert.That(physics.Running,Is.False);Assert.That(editor.Read(pool).containers[0].amountMl,Is.EqualTo(400000));
        }
        [UnityTest]public IEnumerator LiquidAdmissionFailedAcceptedContainerSavePreservesNativeMeshContentsAndHistory(){
            var(_,from,_)=Containers();var view=editor.Find(from).GetComponent<ContainerFillView>();var lease=view.ReusableReservation;var vertices=lease.Mesh.vertices;var material=lease.SurfaceMaterial.GetColor("_Color");var data=editor.Read(from).containers[0];var changed=data.Copy();changed.amountMl=50;changed.radius=.1f;changed.color=Color.red;int revision=editor.Revision;bool undo=editor.CanUndo,redo=editor.CanRedo;Assert.That(editor.TryFlush(out var error),Is.True,error);var bytes=File.ReadAllBytes(Path.Combine(directory,RoomStorage.FileName));
            using(var locked=new FileStream(Path.Combine(directory,RoomStorage.FileName),FileMode.Open,FileAccess.Read,FileShare.Read))Assert.That(editor.EditContainer(from,editor.ObjectRevision(from),changed,out error),Is.False);
            Assert.That(editor.Revision,Is.EqualTo(revision));Assert.That(editor.CanUndo,Is.EqualTo(undo));Assert.That(editor.CanRedo,Is.EqualTo(redo));Assert.That(view.ReusableReservation,Is.SameAs(lease));CollectionAssert.AreEqual(vertices,lease.Mesh.vertices);Assert.That(lease.SurfaceMaterial.GetColor("_Color"),Is.EqualTo(material));Assert.That(JsonUtility.ToJson(editor.Read(from).containers[0]),Is.EqualTo(JsonUtility.ToJson(data)));CollectionAssert.AreEqual(bytes,File.ReadAllBytes(Path.Combine(directory,RoomStorage.FileName)));yield return null;
        }
        [UnityTest]public IEnumerator LiquidAdmissionCapturesPrivateReadyInactiveAndRetiringOwnershipWithoutStartingWater(){
            root.AddComponent<RuntimeDiagnostics>();var data=LiquidAdmissionData();var host=new GameObject("Private liquid owner");host.transform.SetParent(root.transform,false);var view=host.AddComponent<ContainerFillView>();var held=new List<LiquidResources.Lease>();
            using(var candidate=new PreparedRoomLiquid(editor.WorldIdentity,data.id,data.containers,null)){
                try{var preparing=new JArray(LiquidReservations(data.id));var lease=candidate.Lease;Assert.That(lease.Surface.activeInHierarchy||lease.Stream.activeInHierarchy,Is.False);view.ApplyPrepared(data.id,data.containers,candidate);var ready=new JArray(LiquidReservations(data.id));Assert.That(editor.Find(data.id),Is.Null);Assert.That(physics.Running,Is.False);Assert.That(lease.Line.enabled,Is.False);host.SetActive(false);var disabled=new JArray(LiquidReservations(data.id));held=FillLiquidBudget();var budget=CollisionFact("runtime.liquidBudget");var changed=CollisionFact("runtime.liquidBudget");changed["instances"]=0;Assert.That((int)CollisionFact("runtime.liquidBudget")["instances"],Is.EqualTo(32));
                    NativeResourceLifetime.Release(host);UnityEngine.Object.Destroy(host);var retiring=new JArray(LiquidReservations(data.id));Assert.That(retiring.Count,Is.EqualTo(1));Assert.That((string)retiring[0]["phase"],Is.EqualTo("retiring"));Assert.Throws<RoomResourceLimitException>(()=>LiquidResources.Begin(new RoomResourceOwner(editor.WorldIdentity,"retry","liquid")));
                    string path=Environment.GetEnvironmentVariable("MAESTRO_LIQUID_ADMISSION_EVIDENCE");if(!string.IsNullOrEmpty(path))File.WriteAllText(path,new JObject{["budget"]=budget,["preparing"]=preparing,["ready"]=ready,["disabled"]=disabled,["retiring"]=retiring}.ToString());yield return null;Assert.That(LiquidReservations(data.id),Is.Empty);using var retry=LiquidResources.Begin(new RoomResourceOwner(editor.WorldIdentity,"retry","liquid"));
                }finally{ReleaseLiquidBudget(held);if(host){NativeResourceLifetime.Release(host);UnityEngine.Object.Destroy(host);}}
            }
        }
    }
